package kvhttp

/** A transport-independent HTTP request. */
class Request(val method: String, val path: String, val body: () -> ByteArray = { ByteArray(0) })

/** A transport-independent HTTP response. */
class Response(
    val status: Int,
    val body: ByteArray = ByteArray(0),
    val headers: Map<String, String> = emptyMap(),
)

/** Implements the kvhttp routes on top of a [Store]. */
class Handler(private val store: Store) {

    fun handle(request: Request): Response = when {
        request.path == "/health" -> health(request)
        request.path == "/kv" -> listKeys(request)
        request.path.startsWith(ITEM_PREFIX) -> item(request.path.removePrefix(ITEM_PREFIX), request)
        else -> Response(404)
    }

    private fun health(request: Request): Response =
        if (request.method == "GET") text(200, "ok") else methodNotAllowed("GET")

    private fun listKeys(request: Request): Response {
        if (request.method != "GET") return methodNotAllowed("GET")
        val json = store.keys().joinToString(",", "[", "]", transform = ::jsonString)
        return Response(200, json.toByteArray(), mapOf("Content-Type" to "application/json"))
    }

    private fun item(key: String, request: Request): Response {
        if (!KEY_PATTERN.matches(key)) return Response(400)
        return when (request.method) {
            "GET" -> store.lookup(key)
                ?.let { Response(200, it, mapOf("Content-Type" to "application/octet-stream")) }
                ?: Response(404)
            "PUT" -> Response(if (store.put(key, request.body())) 201 else 200)
            "DELETE" -> Response(if (store.delete(key)) 204 else 404)
            else -> methodNotAllowed("GET, PUT, DELETE")
        }
    }

    private companion object {
        const val ITEM_PREFIX = "/kv/"
        val KEY_PATTERN = Regex("[A-Za-z0-9_-]{1,64}")

        fun text(status: Int, s: String) =
            Response(status, s.toByteArray(), mapOf("Content-Type" to "text/plain; charset=utf-8"))

        fun methodNotAllowed(allowed: String) = Response(405, headers = mapOf("Allow" to allowed))

        fun jsonString(s: String): String = buildString(s.length + 2) {
            append('"')
            for (c in s) {
                when {
                    c == '"' -> append("\\\"")
                    c == '\\' -> append("\\\\")
                    c < ' ' -> append("\\u%04x".format(c.code))
                    else -> append(c)
                }
            }
            append('"')
        }
    }
}

package kvhttp

import com.sun.net.httpserver.HttpExchange
import com.sun.net.httpserver.HttpServer
import java.net.InetSocketAddress
import java.util.concurrent.Executors
import kotlin.system.exitProcess

/** Largest accepted request body: 1 MiB values plus generous headroom. */
private const val MAX_BODY = 8 * 1024 * 1024

private const val BACKLOG = 1024

private fun parsePort(s: String?): Int? = s?.toIntOrNull()?.takeIf { it in 1..65535 }

private fun readBody(exchange: HttpExchange): ByteArray {
    val declared = exchange.requestHeaders.getFirst("Content-Length")?.trim()?.toLongOrNull()
    if (declared != null && declared > MAX_BODY) throw PayloadTooLarge()
    val bytes = exchange.requestBody.readNBytes(MAX_BODY + 1)
    if (bytes.size > MAX_BODY) throw PayloadTooLarge()
    return bytes
}

private class PayloadTooLarge : RuntimeException(null, null, false, false)

private fun serve(handler: Handler, exchange: HttpExchange) {
    exchange.use {
        val request = Request(exchange.requestMethod, exchange.requestURI.rawPath) { readBody(exchange) }
        val response = try {
            handler.handle(request)
        } catch (_: PayloadTooLarge) {
            Response(413)
        }
        response.headers.forEach { (name, value) -> exchange.responseHeaders.set(name, value) }
        // -1 tells HttpServer to send `Content-Length: 0` with no body.
        val length = if (response.body.isEmpty()) -1L else response.body.size.toLong()
        exchange.sendResponseHeaders(response.status, length)
        if (response.body.isNotEmpty()) exchange.responseBody.write(response.body)
    }
}

fun main(args: Array<String>) {
    val port = parsePort(args.firstOrNull()) ?: run {
        System.err.println("usage: app <port>")
        exitProcess(2)
    }
    val handler = Handler(Store())
    val server = HttpServer.create(InetSocketAddress("127.0.0.1", port), BACKLOG)
    server.executor = Executors.newVirtualThreadPerTaskExecutor()
    server.createContext("/") { exchange -> serve(handler, exchange) }
    server.start()
    println("kvhttp listening on 127.0.0.1:$port")
}

package kvhttp

import java.util.concurrent.ConcurrentSkipListMap

/** Thread-safe in-memory key-value store. Keys are kept sorted so listing is cheap. */
class Store {
    private val entries = ConcurrentSkipListMap<String, ByteArray>()

    /** Stores [value] under [key]. Returns true if the key was new. */
    fun put(key: String, value: ByteArray): Boolean = entries.put(key, value) == null

    /** Returns the value stored under [key], or null. */
    fun lookup(key: String): ByteArray? = entries[key]

    /** Removes [key]. Returns true if it was present. */
    fun delete(key: String): Boolean = entries.remove(key) != null

    /** Returns every key in ascending order. */
    fun keys(): List<String> = entries.keys.toList()
}
